from __future__ import annotations

import logging
import random
import time
from collections.abc import Callable
from datetime import datetime, timezone
from email.utils import parsedate_to_datetime
from typing import Any

import requests

logger = logging.getLogger(__name__)


class GoogleMapsGroundingError(RuntimeError):
    """Raised when Gemini Maps grounding cannot return a usable response."""

    def __init__(self, message: str, *, attempt_count: int = 1) -> None:
        super().__init__(message)
        self.attempt_count = max(1, int(attempt_count))


class GoogleMapsGroundingClient:
    BASE_URL = "https://generativelanguage.googleapis.com/v1beta/models/{model}:generateContent"

    def __init__(
        self,
        *,
        requests_module: Any = requests,
        sleep_fn: Callable[[float], None] = time.sleep,
        jitter_fn: Callable[[float, float], float] = random.uniform,
    ) -> None:
        self.requests_module = requests_module
        self.sleep_fn = sleep_fn
        self.jitter_fn = jitter_fn

    def generate_grounded_answer(
        self,
        *,
        api_key: str,
        model: str,
        prompt: str,
        latitude: float | None = None,
        longitude: float | None = None,
        enable_widget: bool = False,
        timeout_seconds: int = 10,
        max_attempts: int = 2,
        initial_retry_delay_seconds: float = 0.4,
        retry_delay_cap_seconds: float = 1.5,
        max_retry_after_seconds: float = 2.0,
    ) -> dict[str, Any]:
        normalized_api_key = str(api_key or "").strip()
        if not normalized_api_key:
            raise GoogleMapsGroundingError("missing_api_key")

        normalized_model = self._normalize_model_name(model)
        payload: dict[str, Any] = {
            "contents": [
                {
                    "role": "user",
                    "parts": [{"text": str(prompt or "").strip()}],
                }
            ],
            "tools": [{"googleMaps": {"enableWidget": bool(enable_widget)}}],
        }
        if latitude is not None and longitude is not None:
            payload["toolConfig"] = {
                "retrievalConfig": {
                    "latLng": {
                        "latitude": float(latitude),
                        "longitude": float(longitude),
                    }
                }
            }

        attempt_limit = max(1, int(max_attempts or 1))
        response = None
        attempt = 0
        for attempt in range(1, attempt_limit + 1):
            try:
                response = self.requests_module.post(
                    url=self.BASE_URL.format(model=normalized_model),
                    headers={
                        "Content-Type": "application/json",
                        "x-goog-api-key": normalized_api_key,
                    },
                    json=payload,
                    timeout=int(timeout_seconds or 10),
                )
            except requests.RequestException as exc:
                logger.warning(
                    "Gemini Maps grounding request failed: %s",
                    exc.__class__.__name__,
                )
                if attempt >= attempt_limit:
                    raise GoogleMapsGroundingError(
                        "request_failed",
                        attempt_count=attempt,
                    ) from exc
                self._sleep_before_retry(
                    response=None,
                    attempt=attempt,
                    initial_delay_seconds=initial_retry_delay_seconds,
                    retry_delay_cap_seconds=retry_delay_cap_seconds,
                    max_retry_after_seconds=max_retry_after_seconds,
                )
                continue

            if response.status_code == 200:
                break

            logger.warning(
                "Gemini Maps grounding returned status=%s", response.status_code
            )
            if not self._should_retry_response(
                response=response,
                attempt=attempt,
                attempt_limit=attempt_limit,
                max_retry_after_seconds=max_retry_after_seconds,
            ):
                raise GoogleMapsGroundingError(
                    f"http_{response.status_code}",
                    attempt_count=attempt,
                )
            self._sleep_before_retry(
                response=response,
                attempt=attempt,
                initial_delay_seconds=initial_retry_delay_seconds,
                retry_delay_cap_seconds=retry_delay_cap_seconds,
                max_retry_after_seconds=max_retry_after_seconds,
            )

        if response is None:
            raise GoogleMapsGroundingError(
                "request_failed",
                attempt_count=max(1, attempt),
            )

        try:
            response_payload = response.json()
        except ValueError as exc:
            raise GoogleMapsGroundingError(
                "invalid_json",
                attempt_count=max(1, attempt),
            ) from exc

        if not isinstance(response_payload, dict):
            raise GoogleMapsGroundingError(
                "invalid_payload",
                attempt_count=max(1, attempt),
            )

        normalized_response = self._normalize_response(response_payload)
        normalized_response["attempt_count"] = max(1, attempt)
        return normalized_response

    def _should_retry_response(
        self,
        *,
        response: Any,
        attempt: int,
        attempt_limit: int,
        max_retry_after_seconds: float,
    ) -> bool:
        if attempt >= attempt_limit:
            return False
        status_code = int(getattr(response, "status_code", 0) or 0)
        if status_code == 429:
            retry_after = self._retry_after_seconds(response)
            return retry_after is None or retry_after <= max_retry_after_seconds
        return status_code == 408 or 500 <= status_code <= 599

    def _sleep_before_retry(
        self,
        *,
        response: Any,
        attempt: int,
        initial_delay_seconds: float,
        retry_delay_cap_seconds: float,
        max_retry_after_seconds: float,
    ) -> None:
        retry_after = self._retry_after_seconds(response)
        if retry_after is not None and retry_after <= max_retry_after_seconds:
            self.sleep_fn(max(0.0, retry_after))
            return

        base_delay = max(0.0, float(initial_delay_seconds or 0.0))
        cap = max(base_delay, float(retry_delay_cap_seconds or base_delay))
        delay = min(cap, base_delay * (2 ** max(0, attempt - 1)))
        jitter = max(0.0, self.jitter_fn(0.0, delay * 0.25)) if delay else 0.0
        self.sleep_fn(min(cap, delay + jitter))

    def _retry_after_seconds(self, response: Any) -> float | None:
        if response is None:
            return None
        headers = getattr(response, "headers", None)
        headers_get = getattr(headers, "get", None)
        if not callable(headers_get):
            return None
        raw_value = str(headers_get("Retry-After") or "").strip()
        if not raw_value:
            return None
        try:
            return max(0.0, float(raw_value))
        except ValueError:
            pass
        try:
            retry_at = parsedate_to_datetime(raw_value)
        except (TypeError, ValueError):
            return None
        if retry_at.tzinfo is None:
            retry_at = retry_at.replace(tzinfo=timezone.utc)
        return max(0.0, (retry_at - datetime.now(timezone.utc)).total_seconds())

    def _normalize_model_name(self, model: str) -> str:
        normalized_model = str(model or "").strip() or "gemini-3-flash-preview"
        return normalized_model.removeprefix("gemini/")

    def _normalize_response(self, payload: dict[str, Any]) -> dict[str, Any]:
        candidate = self._first_candidate(payload)
        grounding_metadata_value = candidate.get("groundingMetadata")
        grounding_metadata: dict[str, Any] = (
            grounding_metadata_value
            if isinstance(grounding_metadata_value, dict)
            else {}
        )
        return {
            "answer_text": self._extract_answer_text(candidate),
            "citations": self._normalize_citations(grounding_metadata),
            "grounding_supports": self._normalize_grounding_supports(
                grounding_metadata
            ),
            "google_maps_widget_context_token": self._normalize_text(
                grounding_metadata.get("googleMapsWidgetContextToken")
            ),
        }

    def _first_candidate(self, payload: dict[str, Any]) -> dict[str, Any]:
        candidates = payload.get("candidates")
        if not isinstance(candidates, list) or not candidates:
            return {}
        candidate = candidates[0]
        return candidate if isinstance(candidate, dict) else {}

    def _extract_answer_text(self, candidate: dict[str, Any]) -> str:
        content = candidate.get("content")
        if not isinstance(content, dict):
            return ""
        parts = content.get("parts")
        if not isinstance(parts, list):
            return ""
        return "\n".join(
            text
            for part in parts
            if isinstance(part, dict)
            for text in [self._normalize_text(part.get("text"))]
            if text
        )

    def _normalize_citations(self, grounding_metadata: Any) -> list[dict[str, str]]:
        if not isinstance(grounding_metadata, dict):
            return []
        chunks = grounding_metadata.get("groundingChunks")
        if not isinstance(chunks, list):
            return []
        citations: list[dict[str, str]] = []
        seen_urls: set[str] = set()
        for chunk in chunks:
            if not isinstance(chunk, dict):
                continue
            maps = chunk.get("maps")
            if not isinstance(maps, dict):
                continue
            url = self._normalize_text(maps.get("uri"))
            if not url or url in seen_urls:
                continue
            title = self._normalize_text(maps.get("title")) or url
            citation = {
                "title": title,
                "url": url,
                "source_type": "google_maps",
            }
            place_id = self._normalize_place_id(maps.get("placeId"))
            if place_id:
                citation["place_id"] = place_id
            citations.append(citation)
            seen_urls.add(url)
        return citations

    def _normalize_grounding_supports(
        self, grounding_metadata: Any
    ) -> list[dict[str, Any]]:
        if not isinstance(grounding_metadata, dict):
            return []
        supports = grounding_metadata.get("groundingSupports")
        if not isinstance(supports, list):
            return []
        normalized: list[dict[str, Any]] = []
        for support in supports:
            if not isinstance(support, dict):
                continue
            segment = support.get("segment")
            segment_text = (
                self._normalize_text(segment.get("text"))
                if isinstance(segment, dict)
                else ""
            )
            indices = support.get("groundingChunkIndices")
            citation_indices = (
                [
                    int(index)
                    for index in indices
                    if isinstance(index, int) and index >= 0
                ]
                if isinstance(indices, list)
                else []
            )
            if segment_text or citation_indices:
                normalized.append(
                    {
                        "text": segment_text,
                        "citation_indices": citation_indices,
                    }
                )
        return normalized

    def _normalize_place_id(self, value: Any) -> str:
        normalized = self._normalize_text(value)
        return normalized.removeprefix("places/")

    def _normalize_text(self, value: Any) -> str:
        return str(value or "").strip()

