from __future__ import annotations

from dataclasses import dataclass
from datetime import datetime, time, timedelta, tzinfo
from math import ceil
from typing import Any
from zoneinfo import ZoneInfo, ZoneInfoNotFoundError

from django.conf import settings
from django.contrib.auth.models import User
from django.db.models import Sum
from django.utils import timezone

from family_agent.models import FamilyAgentRun, FamilyAgentUsageEvent
from users.models import FamilyGroup
from users.services.plan_service import family_has_active_subscription

USAGE_STATE_NORMAL = "normal"
USAGE_STATE_BUSY_TODAY = "busy_today"
USAGE_STATE_ALMOST_USED = "almost_used"
USAGE_STATE_PAUSED_DAILY = "paused_daily"
USAGE_STATE_PAUSED_MONTHLY = "paused_monthly"

DAILY_HARD_CAP_MESSAGE = (
    "Clancy has reached today's planning limit. "
    "You can ask for more help after tomorrow's reset."
)
DAILY_WARNING_MESSAGE = (
    "Clancy has been busy today. A few more quick planning requests may still work."
)
MONTHLY_WARNING_MESSAGE = "You're close to this month's Clancy usage limit."
MONTHLY_HARD_CAP_MESSAGE = (
    "Clancy usage resets next month. Upgrade for more planning help."
)
CAPABILITY_UNAVAILABLE_MESSAGE = "This Clancy feature is not available on this plan."
IMAGE_ATTACHMENTS_UNAVAILABLE_MESSAGE = (
    "Photos are not included on the free plan. Upgrade Clancy to attach photos."
)
RUN_PENDING_MESSAGE = "Clancy is still working on the last request. Try again when that response finishes."
GOOGLE_MAPS_GROUNDING_LIMIT_MESSAGE = (
    "Maps grounding is paused for today. Clancy can still help with saved family "
    "context or simpler place lookups."
)
GOOGLE_MAPS_GROUNDING_TOOL_NAME = "google_maps_grounded_answer"


@dataclass(frozen=True)
class FamilyAgentUsageTotals:
    daily_micros: int
    monthly_micros: int
    daily_cap_micros: int
    monthly_warning_micros: int
    monthly_cap_micros: int
    is_paid: bool
    is_override: bool


class FamilyAgentBudgetExceeded(RuntimeError):  # noqa: N818
    def __init__(self, public_payload: dict[str, Any]) -> None:
        super().__init__(str(public_payload.get("message") or "Clancy usage paused."))
        self.public_payload = public_payload


def estimate_text_tokens(text: str) -> int:
    normalized_text = str(text or "")
    if not normalized_text:
        return 0
    return max(4, ceil(len(normalized_text) / 3))


def estimate_cost_micros(*, input_tokens: int, output_tokens: int) -> int:
    input_rate = int(
        getattr(
            settings,
            "FAMILY_AGENT_GEMINI_3_FLASH_INPUT_COST_MICROS_PER_M_TOKEN",
            500_000,
        )
    )
    output_rate = int(
        getattr(
            settings,
            "FAMILY_AGENT_GEMINI_3_FLASH_OUTPUT_COST_MICROS_PER_M_TOKEN",
            3_000_000,
        )
    )
    raw_cost = max(0, input_tokens) * input_rate + max(0, output_tokens) * output_rate
    return int((raw_cost + 999_999) // 1_000_000)


class FamilyAgentBudgetService:
    def get_public_usage_status(
        self,
        *,
        family: FamilyGroup,
        user: User,
    ) -> dict[str, Any]:
        totals = self._get_usage_totals(family=family, user=user)
        return self._build_public_status(totals)

    def enforce_budget(
        self,
        *,
        family: FamilyGroup,
        user: User,
        estimated_increment_micros: int = 0,
    ) -> None:
        totals = self._get_usage_totals(family=family, user=user)
        if totals.is_override:
            return

        increment = max(0, int(estimated_increment_micros))
        if totals.daily_cap_micros > 0 and (
            totals.daily_micros + increment > totals.daily_cap_micros
        ):
            raise FamilyAgentBudgetExceeded(
                self._build_limit_payload(
                    totals,
                    usage_state=USAGE_STATE_PAUSED_DAILY,
                    daily_state=USAGE_STATE_PAUSED_DAILY,
                    monthly_state=self._monthly_state(totals.monthly_micros, totals),
                    message=DAILY_HARD_CAP_MESSAGE,
                    reset_hint="tomorrow",
                )
            )

        if totals.monthly_cap_micros > 0 and (
            totals.monthly_micros + increment > totals.monthly_cap_micros
        ):
            raise FamilyAgentBudgetExceeded(
                self._build_limit_payload(
                    totals,
                    usage_state=USAGE_STATE_PAUSED_MONTHLY,
                    daily_state=self._daily_state(totals.daily_micros, totals),
                    monthly_state=USAGE_STATE_PAUSED_MONTHLY,
                    message=MONTHLY_HARD_CAP_MESSAGE,
                    reset_hint="next_month",
                )
            )

    def estimate_preflight_cost_micros(
        self,
        *,
        message_text: str,
        image_count: int = 0,
    ) -> int:
        base_input_tokens = int(
            getattr(settings, "FAMILY_AGENT_PREFLIGHT_INPUT_TOKENS", 6_000)
        )
        expected_output_tokens = int(
            getattr(settings, "FAMILY_AGENT_PREFLIGHT_OUTPUT_TOKENS", 1_200)
        )
        image_input_tokens = int(
            getattr(settings, "FAMILY_AGENT_PREFLIGHT_IMAGE_INPUT_TOKENS", 1_500)
        ) * max(0, image_count)
        input_tokens = (
            base_input_tokens + estimate_text_tokens(message_text) + image_input_tokens
        )
        return estimate_cost_micros(
            input_tokens=input_tokens,
            output_tokens=expected_output_tokens,
        )

    def estimate_prompt_cost_micros(
        self,
        *,
        system_message: str,
        user_prompt: str,
        expected_output_tokens: int | None = None,
    ) -> tuple[int, int, int]:
        input_tokens = estimate_text_tokens(system_message) + estimate_text_tokens(
            user_prompt
        )
        output_tokens = int(
            expected_output_tokens
            if expected_output_tokens is not None
            else getattr(settings, "FAMILY_AGENT_RUNTIME_OUTPUT_TOKENS", 1_200)
        )
        cost_micros = estimate_cost_micros(
            input_tokens=input_tokens,
            output_tokens=output_tokens,
        )
        return input_tokens, output_tokens, cost_micros

    def get_capability_flags(
        self,
        *,
        family: FamilyGroup,
        user: User,
    ) -> dict[str, bool]:
        is_override = self._has_staff_override(user)
        is_paid = self._is_paid_family(family) or is_override
        return self._compute_capability_flags(is_paid=is_paid, is_override=is_override)

    def _compute_capability_flags(
        self, *, is_paid: bool, is_override: bool
    ) -> dict[str, bool]:
        free_images_enabled = bool(
            getattr(settings, "FAMILY_AGENT_FREE_IMAGE_ATTACHMENTS_ENABLED", False)
        )
        free_research_enabled = bool(
            getattr(settings, "FAMILY_AGENT_FREE_EXTERNAL_RESEARCH_ENABLED", False)
        )
        paid_research_enabled = bool(
            getattr(settings, "FAMILY_AGENT_PAID_EXTERNAL_RESEARCH_ENABLED", False)
        )
        paid_or_override = is_paid or is_override
        return {
            "image_attachments_enabled": bool(paid_or_override or free_images_enabled),
            "external_research_enabled": bool(
                is_override
                or free_research_enabled
                or (paid_or_override and paid_research_enabled)
            ),
        }

    def record_usage(
        self,
        *,
        family: FamilyGroup,
        user: User | None,
        run: FamilyAgentRun | None,
        operation: str,
        status: str,
        model_name: str,
        estimated_input_tokens: int = 0,
        estimated_output_tokens: int = 0,
        estimated_total_cost_micros: int = 0,
        tool_call_count: int = 0,
        image_count: int = 0,
        metadata_json: dict[str, Any] | None = None,
    ) -> FamilyAgentUsageEvent:
        return FamilyAgentUsageEvent.objects.create(
            family=family,
            user=user,
            run=run,
            operation=operation,
            status=status,
            model_name=model_name,
            estimated_input_tokens=max(0, int(estimated_input_tokens)),
            estimated_output_tokens=max(0, int(estimated_output_tokens)),
            estimated_total_cost_micros=max(0, int(estimated_total_cost_micros)),
            tool_call_count=max(0, int(tool_call_count)),
            image_count=max(0, int(image_count)),
            metadata_json=metadata_json or {},
        )

    def enforce_google_maps_grounding_call_budget(
        self,
        *,
        family: FamilyGroup,
        user: User,
    ) -> None:
        if self._has_staff_override(user):
            return

        cap = self._google_maps_grounding_daily_call_cap()
        if cap <= 0:
            return

        now = timezone.now()
        day_start, day_end, _, _ = self._period_bounds(user=user, now=now)
        used_calls = (
            FamilyAgentUsageEvent.objects.filter(
                family=family,
                created_at__gte=day_start,
                created_at__lt=day_end,
                operation=FamilyAgentUsageEvent.Operation.TOOL_LOOP,
                metadata_json__tool_name=GOOGLE_MAPS_GROUNDING_TOOL_NAME,
            )
            .exclude(status=FamilyAgentUsageEvent.Status.BLOCKED)
            .count()
        )
        if used_calls >= cap:
            raise FamilyAgentBudgetExceeded(
                {
                    "code": "family_agent_maps_grounding_paused",
                    "usage_state": USAGE_STATE_BUSY_TODAY,
                    "daily_state": USAGE_STATE_BUSY_TODAY,
                    "monthly_state": USAGE_STATE_NORMAL,
                    "reset_hint": "tomorrow",
                    "capability_flags": self.get_capability_flags(
                        family=family,
                        user=user,
                    ),
                    "upgrade_available": not self._is_paid_family(family),
                    "message": GOOGLE_MAPS_GROUNDING_LIMIT_MESSAGE,
                }
            )

    def _get_usage_totals(
        self,
        *,
        family: FamilyGroup,
        user: User,
    ) -> FamilyAgentUsageTotals:
        now = timezone.now()
        day_start, day_end, month_start, month_end = self._period_bounds(
            user=user,
            now=now,
        )
        is_override = self._has_staff_override(user)
        is_paid = self._is_paid_family(family)
        return FamilyAgentUsageTotals(
            daily_micros=self._sum_usage_micros(
                family=family,
                start=day_start,
                end=day_end,
            ),
            monthly_micros=self._sum_usage_micros(
                family=family,
                start=month_start,
                end=month_end,
            ),
            daily_cap_micros=self._daily_cap_micros(is_paid=is_paid),
            monthly_warning_micros=self._monthly_warning_micros(is_paid=is_paid),
            monthly_cap_micros=self._monthly_cap_micros(is_paid=is_paid),
            is_paid=is_paid,
            is_override=is_override,
        )

    def _sum_usage_micros(
        self,
        *,
        family: FamilyGroup,
        start: datetime,
        end: datetime,
    ) -> int:
        result = FamilyAgentUsageEvent.objects.filter(
            family=family,
            created_at__gte=start,
            created_at__lt=end,
            status__in=[
                FamilyAgentUsageEvent.Status.COMPLETED,
                FamilyAgentUsageEvent.Status.FAILED,
            ],
        ).aggregate(total=Sum("estimated_total_cost_micros"))
        return int(result["total"] or 0)

    def _period_bounds(
        self,
        *,
        user: User,
        now: datetime,
    ) -> tuple[datetime, datetime, datetime, datetime]:
        budget_tz = self._resolve_budget_timezone()
        local_now = now.astimezone(budget_tz)
        day_start = datetime.combine(local_now.date(), time.min, tzinfo=budget_tz)
        day_end = day_start + timedelta(days=1)
        month_start = datetime(local_now.year, local_now.month, 1, tzinfo=budget_tz)
        if local_now.month == 12:
            month_end = datetime(local_now.year + 1, 1, 1, tzinfo=budget_tz)
        else:
            month_end = datetime(
                local_now.year, local_now.month + 1, 1, tzinfo=budget_tz
            )
        return day_start, day_end, month_start, month_end

    def _resolve_budget_timezone(self) -> tzinfo:
        configured_name = str(
            getattr(
                settings,
                "FAMILY_AGENT_BUDGET_TIME_ZONE",
                getattr(settings, "TIME_ZONE", "UTC"),
            )
            or "UTC"
        )
        try:
            return ZoneInfo(configured_name)
        except ZoneInfoNotFoundError:
            fallback_name = str(getattr(settings, "TIME_ZONE", "UTC") or "UTC")
            try:
                return ZoneInfo(fallback_name)
            except ZoneInfoNotFoundError:
                return ZoneInfo("UTC")

    def _is_paid_family(self, family: FamilyGroup) -> bool:
        if getattr(family, "is_grandfathered", False):
            return True
        return family_has_active_subscription(family)

    def _has_staff_override(self, user: User) -> bool:
        return bool(getattr(user, "is_staff", False))

    def _daily_cap_micros(self, *, is_paid: bool) -> int:
        if is_paid:
            return int(
                getattr(settings, "FAMILY_AGENT_PAID_DAILY_COST_CAP_MICROS", 3_000_000)
            )
        return int(getattr(settings, "FAMILY_AGENT_FREE_DAILY_COST_CAP_MICROS", 70_000))

    def _monthly_warning_micros(self, *, is_paid: bool) -> int:
        if is_paid:
            return int(
                getattr(
                    settings, "FAMILY_AGENT_PAID_MONTHLY_WARNING_COST_MICROS", 1_500_000
                )
            )
        return int(
            getattr(settings, "FAMILY_AGENT_FREE_MONTHLY_WARNING_COST_MICROS", 500_000)
        )

    def _monthly_cap_micros(self, *, is_paid: bool) -> int:
        if is_paid:
            return int(
                getattr(
                    settings, "FAMILY_AGENT_PAID_MONTHLY_COST_CAP_MICROS", 3_000_000
                )
            )
        return int(
            getattr(settings, "FAMILY_AGENT_FREE_MONTHLY_COST_CAP_MICROS", 750_000)
        )

    def _google_maps_grounding_daily_call_cap(self) -> int:
        return int(
            getattr(settings, "FAMILY_AGENT_GOOGLE_MAPS_GROUNDING_DAILY_CALL_CAP", 20)
        )

    def _daily_state(
        self,
        daily_micros: int,
        totals: FamilyAgentUsageTotals,
    ) -> str:
        if totals.is_override or totals.daily_cap_micros <= 0:
            return USAGE_STATE_NORMAL
        if daily_micros >= totals.daily_cap_micros:
            return USAGE_STATE_PAUSED_DAILY
        warning_micros = int(totals.daily_cap_micros * 0.8)
        if warning_micros > 0 and daily_micros >= warning_micros:
            return USAGE_STATE_BUSY_TODAY
        return USAGE_STATE_NORMAL

    def _monthly_state(
        self,
        monthly_micros: int,
        totals: FamilyAgentUsageTotals,
    ) -> str:
        if totals.is_override:
            return USAGE_STATE_NORMAL
        if (
            totals.monthly_cap_micros > 0
            and monthly_micros >= totals.monthly_cap_micros
        ):
            return USAGE_STATE_PAUSED_MONTHLY
        if (
            totals.monthly_warning_micros > 0
            and monthly_micros >= totals.monthly_warning_micros
        ):
            return USAGE_STATE_ALMOST_USED
        return USAGE_STATE_NORMAL

    def _build_public_status(self, totals: FamilyAgentUsageTotals) -> dict[str, Any]:
        daily_state = self._daily_state(totals.daily_micros, totals)
        monthly_state = self._monthly_state(totals.monthly_micros, totals)
        if monthly_state == USAGE_STATE_PAUSED_MONTHLY:
            usage_state = USAGE_STATE_PAUSED_MONTHLY
            reset_hint = "next_month"
        elif daily_state == USAGE_STATE_PAUSED_DAILY:
            usage_state = USAGE_STATE_PAUSED_DAILY
            reset_hint = "tomorrow"
        elif monthly_state == USAGE_STATE_ALMOST_USED:
            usage_state = USAGE_STATE_ALMOST_USED
            reset_hint = "next_month"
        elif daily_state == USAGE_STATE_BUSY_TODAY:
            usage_state = USAGE_STATE_BUSY_TODAY
            reset_hint = "tomorrow"
        else:
            usage_state = USAGE_STATE_NORMAL
            reset_hint = "none"

        return {
            "usage_state": usage_state,
            "daily_state": daily_state,
            "monthly_state": monthly_state,
            "reset_hint": reset_hint,
            "capability_flags": self._capability_flags_from_totals(totals),
            "upgrade_available": not totals.is_paid and not totals.is_override,
        }

    def _build_limit_payload(
        self,
        totals: FamilyAgentUsageTotals,
        *,
        usage_state: str,
        daily_state: str,
        monthly_state: str,
        message: str,
        reset_hint: str,
    ) -> dict[str, Any]:
        return {
            "code": "family_agent_usage_paused",
            "usage_state": usage_state,
            "daily_state": daily_state,
            "monthly_state": monthly_state,
            "reset_hint": reset_hint,
            "capability_flags": self._capability_flags_from_totals(totals),
            "upgrade_available": not totals.is_paid and not totals.is_override,
            "message": message,
        }

    def _capability_flags_from_totals(
        self,
        totals: FamilyAgentUsageTotals,
    ) -> dict[str, bool]:
        return self._compute_capability_flags(
            is_paid=totals.is_paid, is_override=totals.is_override
        )

        return "custom"
    return self.provider

def _build_agent(self) -> Any:
    from run_agent import AIAgent

    if not self.provider:
        raise RuntimeError(
            "Family planner could not determine an LLM provider from "
            f"FAMILY_AGENT_HERMES_MODEL={self.model_name!r}. "
            "Set FAMILY_AGENT_HERMES_PROVIDER explicitly."
        )
    if not self.api_key:
        raise RuntimeError(
            "Family planner is missing API credentials for "
            f"provider '{self.provider}'. Set {self.api_key_setting_name} "
            "in the backend environment."
        )

    return AIAgent(
        model=self.agent_model_name,
        provider=self.hermes_provider,
        api_key=self.api_key,
        base_url=self.base_url or None,
        quiet_mode=True,
        enabled_toolsets=["web", "browser"]
        if self.external_research_enabled
        else [],
        skip_memory=True,
        skip_context_files=True,
        max_iterations=self.max_iterations,
    )

def _normalize_request_scope_text(self, value: Any) -> str:
    return re.sub(r"\s+", " ", str(value or "")).strip().lower()

def _classify_request_scope(
    self,
    *,
    message_text: str,
    context: dict[str, Any],
) -> tuple[str, str]:
    normalized_message = self._normalize_request_scope_text(message_text)
    request_context = context.get("request_context")
    if not isinstance(request_context, dict):
        request_context = {}

    source_screen = self._normalize_request_scope_text(
        request_context.get("source_screen")
    )
    has_attachment_context = bool(
        context.get("current_message_attachments")
    ) or bool(
        self._normalize_request_scope_text(
            context.get("current_message_attachment_summary")
        )
    )
    has_focus_context = (
        any(
            str(request_context.get(key) or "").strip()
            for key in ("event_id", "trip_id", "group_id", "capture_id")
        )
        or bool(context.get("focused_event"))
        or bool(context.get("focused_capture"))
    )
    has_organize_context = source_screen in {
        "today",
        "desktop_home",
        "desktop_capture",
        "desktop_shopping",
    } and any(
        context.get(key)
        for key in ("task_snapshot", "list_snapshot", "chore_snapshot")
    )
    has_thread_context = bool(context.get("recent_messages"))
    has_planner_topic_term = any(
        term in normalized_message for term in _PLANNER_TOPIC_TERMS
    )
    has_calendar_link_signal = bool(
        re.search(
            r"\bwebcal://\S+|\bhttps?://\S+\.ics(?:[?#]\S*)?",
            normalized_message,
            flags=re.IGNORECASE,
        )
    )
    has_schedule_term = any(
        term in normalized_message for term in _PLANNER_SCHEDULE_TERMS
    ) or bool(
        re.search(
            r"\b\d{1,2}(?::\d{2})?\s?(?:a\.?m\.?|p\.?m\.?)\b",
            normalized_message,
            flags=re.IGNORECASE,
        )
    )
    has_planner_intent = any(
        re.search(pattern, normalized_message, flags=re.IGNORECASE)
        for pattern in _PLANNER_INTENT_PATTERNS
    )
    has_out_of_scope_intent = any(
        re.search(pattern, normalized_message, flags=re.IGNORECASE)
        for pattern in _OUT_OF_SCOPE_REQUEST_PATTERNS
    )

    if has_out_of_scope_intent:
        return _REQUEST_SCOPE_OUT_OF_SCOPE, "generic_request"
    if has_attachment_context:
        return _REQUEST_SCOPE_IN_SCOPE, "attachment_context"
    if has_focus_context:
        return _REQUEST_SCOPE_IN_SCOPE, "focused_context"
    if has_calendar_link_signal:
        return _REQUEST_SCOPE_IN_SCOPE, "calendar_link"
    if has_planner_topic_term:
        return _REQUEST_SCOPE_IN_SCOPE, "planner_keywords"
    if has_organize_context and (has_planner_intent or has_schedule_term):
        return _REQUEST_SCOPE_IN_SCOPE, "organize_context"
    if has_thread_context and (has_planner_intent or has_schedule_term):
        return _REQUEST_SCOPE_IN_SCOPE, "thread_follow_up"
    if source_screen in _PLANNER_CONTEXT_SCREENS and has_planner_intent:
        return _REQUEST_SCOPE_IN_SCOPE, "screen_context"
    if has_planner_intent:
        return _REQUEST_SCOPE_IN_SCOPE, "planner_intent"
    if has_schedule_term and source_screen in _PLANNER_CONTEXT_SCREENS:
        return _REQUEST_SCOPE_IN_SCOPE, "screen_schedule_reference"
    return _REQUEST_SCOPE_OUT_OF_SCOPE, "no_planner_signal"

def build_context(
    self,
    *,
    user: User,
    family: FamilyGroup,
    message_text: str,
    context_payload: dict[str, Any],
    thread: Any = None,
    trigger_message: FamilyAgentMessage | None = None,
) -> dict[str, Any]:
    context = self.tool_adapter.build_runtime_context(
        user=user,
        family=family,
        thread=thread,
        trigger_message=trigger_message,
        message_text=message_text,
        context_payload=context_payload,
    )
    normalized_context = dict(context)
    normalized_context.pop("events", None)
    normalized_context["planner_clock"] = self._build_planner_clock()
    normalized_context["availability_tools"] = (
        self._build_availability_tool_context()
    )
    normalized_context["external_research_route"] = (
        self._build_external_research_route_context(message_text=message_text)
    )
    normalized_context["tool_contracts"] = describe_tool_contracts()
    coerced: dict[str, Any] = coerce_for_json(normalized_context)
    return coerced

def _build_external_research_route_context(
    self,
    *,
    message_text: str,
) -> dict[str, Any]:
    normalized_message = self._normalize_request_scope_text(message_text)
    explicit_maps_sources = "google maps" in normalized_message
    has_geo_signal = any(term in normalized_message for term in _GEO_RESEARCH_TERMS)
    has_geo_recommendation = any(
        term in normalized_message for term in _GEO_RECOMMENDATION_TERMS
    )
    has_official_fact_request = any(
        term in normalized_message for term in _OFFICIAL_WEB_RESEARCH_TERMS
    )
    has_structured_maps_request = any(
        term in normalized_message for term in _MAPS_STRUCTURED_RESEARCH_TERMS
    )

    route = "none"
    reason = "no_external_research_signal"
    fallback_route = "none"
    if explicit_maps_sources:
        route = "maps_grounding"
        reason = "explicit_google_maps_sources"
        fallback_route = "maps_structured"
    elif has_official_fact_request:
        route = "web_research"
        reason = "official_non_place_fact"
        fallback_route = "maps_grounding" if has_geo_signal else "none"
    elif has_structured_maps_request and has_geo_signal:
        route = "maps_structured"
        reason = "structured_maps_lookup"
        fallback_route = "maps_grounding"
    elif has_geo_signal and has_geo_recommendation:
        route = "maps_grounding"
        reason = "open_ended_geo_recommendation"
        fallback_route = "maps_structured"
    elif has_geo_signal:
        route = "maps_grounding"
        reason = "geo_place_question"
        fallback_route = "web_research"

    return {
        "route": route,
        "reason": reason,
        "fallback_route": fallback_route,
        "stickiness": "single_route_per_turn",
        "allowed_route_changes": [
            "tool_result_ok_false",
            "tool_result_lacks_requested_fact",
            "user_explicitly_changes_source",
        ],
    }

def _build_availability_tool_context(self) -> dict[str, Any]:
    return {
        "tool_names": [
            "query_calendar_day",
            "query_calendar_blocks",
            "check_time_blocked",
            "get_event_details",
            "search_calendar_events",
            "get_user_location",
            "find_nearby_restaurants",
            "google_maps_grounded_answer",
            "search_ucp_products",
        ],
        "google_maps_grounding": {
            "enabled": bool(
                self.external_research_enabled
                and getattr(
                    settings,
                    "FAMILY_AGENT_GOOGLE_MAPS_GROUNDING_ENABLED",
                    False,
                )
            ),
            "best_for": (
                "Conversational local recommendations, trip-planning, place "
                "questions, and family-friendly nearby activity research."
            ),
        },
        "scopes": {
            "immediate_family": {
                "description": "Full planner visibility for the current immediate family.",
                "member_filters_supported": True,
            },
            "network_public": {
                "description": "Only PUBLIC events from connected families in the active META network.",
                "member_filters_supported": False,
                "requires_group_id": True,
            },
        },
        "member_filter_examples": ["user:123", "child:456"],
        "household_block_behavior": (
            "When member filters are used, unassociated household events still "
            "appear as household blocks."
        ),
        "default_detail": "lightweight_blocks",
    }

def _planner_timezone(self) -> ZoneInfo:
    cached = getattr(self, "_planner_timezone_cache", None)
    if cached is None:
        cached = ZoneInfo(str(getattr(settings, "TIME_ZONE", "America/New_York")))
        self._planner_timezone_cache = cached
    return cached

def _local_day_bounds(self, local_date: date) -> tuple[datetime, datetime]:
    local_start = datetime.combine(
        local_date,
        time.min,
        tzinfo=self._planner_timezone(),
    )
    return local_start, local_start + timedelta(days=1)

def _build_planner_clock(self) -> dict[str, Any]:
    tz = self._planner_timezone()
    local_now = timezone.localtime(timezone.now(), tz)
    today_start, today_end = self._local_day_bounds(local_now.date())
    return {
        "timezone": str(tz),
        "local_now": local_now.isoformat(),
        "local_date": local_now.date().isoformat(),
        "today_start_time": today_start.isoformat(),
        "today_end_time": today_end.isoformat(),
    }

def _resolve_local_day_request(
    self,
    *,
    message_text: str,
    context_payload: dict[str, Any],
) -> date | None:
    selected_date = self.tool_adapter._parse_selected_date(
        context_payload.get("selected_date")
    )
    if selected_date is not None:
        return selected_date

    if re.search(r"\b(?:today(?:['’]s)?|tonight)\b", message_text.lower()):
        return timezone.localtime(timezone.now(), self._planner_timezone()).date()

    return None

def _is_calendar_day_window(self, start_time: datetime, end_time: datetime) -> bool:
    duration = end_time - start_time
    if not timedelta(hours=23) <= duration <= timedelta(hours=25):
        return False
    return start_time.time() == time.min and end_time.time() == time.min

def _normalize_local_day_tool_arguments(
    self,
    *,
    tool_name: str,
    arguments: dict[str, Any],
    message_text: str,
    context_payload: dict[str, Any],
) -> dict[str, Any]:
    if tool_name not in _LOCAL_DAY_CALENDAR_TOOLS:
        return arguments

    local_date = self._resolve_local_day_request(
        message_text=message_text,
        context_payload=context_payload,

