  function loadGoogleMapsContextualView(apiKey) {
    const normalizedApiKey = String(apiKey || '').trim();
    if (!normalizedApiKey) {
      return Promise.reject(new Error('Missing Google Maps browser API key.'));
    }
    if (window.google?.maps?.importLibrary) {
      return Promise.resolve();
    }
    if (googleMapsContextualViewPromise) {
      return googleMapsContextualViewPromise;
    }

    googleMapsContextualViewPromise = new Promise((resolve, reject) => {
      const script = document.createElement('script');
      script.src = `https://maps.googleapis.com/maps/api/js?key=${encodeURIComponent(normalizedApiKey)}&v=alpha&libraries=places`;
      script.async = true;
      script.defer = true;
      script.onload = resolve;
      script.onerror = () => reject(new Error('Unable to load Google Maps widget.'));
      document.head.appendChild(script);
    });
    return googleMapsContextualViewPromise;
  }

  function renderGoogleMapsGroundingWidget(contextJson, cards, options) {
    const settings = options || {};
    const contextToken = getGoogleMapsWidgetToken(contextJson);
    const apiKey = String(settings.apiKey || '').trim();
    if (!contextToken || !cards || !apiKey) {
      return;
    }

    const card = document.createElement('div');
    card.className = settings.cardClassName || 'clancy-agent-card clancy-google-maps-widget';
    const label = document.createElement('div');
    label.className = settings.labelClassName || 'clancy-card-label';
    label.textContent = 'Map context';
    const host = document.createElement('div');
    host.className = settings.hostClassName || 'clancy-google-maps-widget-host';
    card.append(label, host);
    cards.appendChild(card);

    void loadGoogleMapsContextualView(apiKey)
      .then(async () => {
        await window.google.maps.importLibrary('places');
        const places = window.google.maps.places;
        const widget = new places.PlaceContextualElement({ contextToken });
