def test_google_maps_grounding_client_posts_native_gemini_maps_tool() -> None:
    fake_requests = _FakeRequests(_FakeResponse(200, _maps_success_payload()))

    result = GoogleMapsGroundingClient(
        requests_module=fake_requests,
    ).generate_grounded_answer(
        api_key="fake-gemini-key",  # pragma: allowlist secret
        model="gemini-3-flash-preview",
        prompt="Best coffee nearby",
        latitude=40.758896,
        longitude=-73.98513,
        enable_widget=True,
        timeout_seconds=7,
    )

    assert result["answer_text"] == "CanteenM is open nearby."
    assert result["citations"] == [
        {
            "title": "CanteenM",
            "url": "https://maps.google.com/?cid=123",
            "place_id": "ChIJ-canteenm",
            "source_type": "google_maps",
        }
    ]
    assert result["grounding_supports"] == [
        {
            "text": "CanteenM is open nearby.",
            "citation_indices": [0],
        }
    ]
    assert result["google_maps_widget_context_token"] == "widgetcontent/abc"  # noqa: S105
    assert result["attempt_count"] == 1

    [call] = fake_requests.calls
    assert call["url"].endswith("/v1beta/models/gemini-3-flash-preview:generateContent")
    assert (
        call["headers"]["x-goog-api-key"] == "fake-gemini-key"
    )  # pragma: allowlist secret
    assert call["timeout"] == 7
    assert call["json"]["tools"] == [{"googleMaps": {"enableWidget": True}}]
    assert call["json"]["toolConfig"]["retrievalConfig"]["latLng"] == {
        "latitude": 40.758896,
        "longitude": -73.98513,
    }


