def test_google_maps_grounding_client_retries_transient_http_error() -> None:
    fake_requests = _QueuedFakeRequests(
        [
            _FakeResponse(503, {"error": {"message": "unavailable"}}),
            _FakeResponse(200, _maps_success_payload()),
        ]
    )
    sleeps: list[float] = []

    result = GoogleMapsGroundingClient(
        requests_module=fake_requests,
        sleep_fn=sleeps.append,
        jitter_fn=lambda _minimum, _maximum: 0,
    ).generate_grounded_answer(
        api_key="fake-gemini-key",  # pragma: allowlist secret
        model="gemini-3-flash-preview",
        prompt="Best coffee nearby",
        max_attempts=2,
        initial_retry_delay_seconds=0.25,
    )

    assert result["answer_text"] == "CanteenM is open nearby."
    assert result["attempt_count"] == 2
    assert len(fake_requests.calls) == 2
    assert sleeps == [0.25]


