)
def test_google_maps_grounded_answer_resolves_event_coordinates() -> None:
    family, user = _create_family_user(username="maps_event_admin")
    event = Event.objects.create(
        title="Neshanic FC vs Stars",
        family_group=family,
        creator=user,
        location="Soccer Park, Neshanic Station, NJ",
        latitude=40.5195,
        longitude=-74.7337,
        start_time=datetime(2026, 6, 12, 10, 0, tzinfo=dt_tz.utc),
        end_time=datetime(2026, 6, 12, 11, 0, tzinfo=dt_tz.utc),
    )
    fake_client = _FakeGroundingClient()

    result = FamilyPlannerToolAdapter(
        google_maps_grounding_client=fake_client,
    ).google_maps_grounded_answer(
        user=user,
        family=family,
        query="Best family-friendly dinner after the game",
        event_id=str(event.id),
        enable_widget=True,
    )

    assert result["ok"] is True
    assert result["answer_text"] == "Riverside Inn is a strong post-game dinner option."
    assert result["citations"][0]["source_type"] == "google_maps"
    assert (
        result["google_maps_widget_context_token"] == "widgetcontent/test-token"  # noqa: S105
    )
    assert result["origin"] == {
        "latitude": 40.5195,
        "longitude": -74.7337,
        "near_label": "Soccer Park, Neshanic Station, NJ",
    }
    [call] = fake_client.calls
    assert call["api_key"] == "fake-maps-key"  # pragma: allowlist secret
    assert call["latitude"] == pytest.approx(40.5195)
    assert call["longitude"] == pytest.approx(-74.7337)
    assert call["enable_widget"] is True
    assert "Soccer Park, Neshanic Station, NJ" in call["prompt"]


