    FAMILY_AGENT_GOOGLE_MAPS_GROUNDING_ENABLED=True,
    GOOGLE_MAPS_GROUNDING_API_KEY="fake-maps-key",  # pragma: allowlist secret
    FAMILY_AGENT_GOOGLE_MAPS_GROUNDING_ENABLE_WIDGET=True,
)
def test_google_maps_grounded_answer_enables_widget_for_supported_web_context() -> None:
    family, user = _create_family_user(username="maps_widget_web_admin")
    fake_client = _FakeGroundingClient()

    FamilyPlannerToolAdapter(
        google_maps_grounding_client=cast(GoogleMapsGroundingClient, fake_client),
    ).google_maps_grounded_answer(
        user=user,
        family=family,
        query="What should we do near our hotel?",
        context_payload={"google_maps_widget_supported": True},
    )

    [call] = fake_client.calls
    assert call["enable_widget"] is True


@pytest.mark.django_db
@override_settings(
    FAMILY_AGENT_GOOGLE_MAPS_GROUNDING_ENABLED=False,
    GOOGLE_MAPS_GROUNDING_API_KEY="fake-maps-key",  # pragma: allowlist secret
)
def test_google_maps_grounded_answer_returns_error_when_disabled() -> None:
    family, user = _create_family_user(username="maps_disabled_admin")
    fake_client = _FakeGroundingClient()

    result = FamilyPlannerToolAdapter(
        google_maps_grounding_client=fake_client,
    ).google_maps_grounded_answer(
        user=user,
        family=family,
        query="Best coffee nearby",
    )

    assert result["ok"] is False
    assert "not enabled" in result["error"].lower()
    assert fake_client.calls == []


